import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import api from '../../utils/api';
import LoadingSpinner from '../../components/LoadingSpinner';
import './AllPets.css';

const AllPets = () => {
  const [pets, setPets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [species, setSpecies] = useState('All');
  const [sort, setSort] = useState('newest');
  
  // Use ref for search to prevent re-renders
  const searchInputRef = useRef(null);
  const timeoutRef = useRef(null);

  // Fetch pets when species or sort changes
  useEffect(() => {
    fetchPets();
  }, [species, sort]);

  const fetchPets = async (searchTerm = '') => {
    setLoading(true);
    try {
      const res = await api.get('/pets', {
        params: { 
          search: searchTerm, 
          species, 
          sort 
        }
      });
      setPets(res.data);
    } catch (error) {
      console.error('Error fetching pets:', error);
    } finally {
      setLoading(false);
    }
  };

  // Handle search with debounce without losing focus
  const handleSearch = (e) => {
    const value = e.target.value;
    
    // Clear previous timeout
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    
    // Set new timeout to search after user stops typing
    timeoutRef.current = setTimeout(() => {
      fetchPets(value);
    }, 500);
  };

  const handleSpeciesChange = (e) => {
    const newSpecies = e.target.value;
    setSpecies(newSpecies);
    // Also search with current search input value
    const currentSearchValue = searchInputRef.current?.value || '';
    fetchPets(currentSearchValue);
  };

  const handleSortChange = (e) => {
    const newSort = e.target.value;
    setSort(newSort);
    // Also search with current search input value
    const currentSearchValue = searchInputRef.current?.value || '';
    fetchPets(currentSearchValue);
  };

  const clearAllFilters = () => {
    // Clear search input
    if (searchInputRef.current) {
      searchInputRef.current.value = '';
    }
    // Reset filters
    setSpecies('All');
    setSort('newest');
    // Fetch all pets
    fetchPets('');
  };

  if (loading) return <LoadingSpinner />;

  return (
    <div className="container">
      <div className="all-pets-header">
        <h1>Find Your Perfect Companion</h1>
        <p>Browse our available pets waiting for a loving home</p>
      </div>

      <div className="filters-section">
        <div className="search-box">
          <input
            ref={searchInputRef}
            type="text"
            placeholder="Search by name..."
            onChange={handleSearch}
            autoComplete="off"
          />
        </div>
        
        <div className="filter-group">
          <select value={species} onChange={handleSpeciesChange}>
            <option value="All">All Species</option>
            <option value="Dog">Dogs</option>
            <option value="Cat">Cats</option>
            <option value="Bird">Birds</option>
            <option value="Rabbit">Rabbits</option>
            <option value="Other">Other</option>
          </select>
          
          <select value={sort} onChange={handleSortChange}>
            <option value="newest">Newest First</option>
            <option value="oldest">Oldest First</option>
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
          </select>
        </div>
      </div>

      {pets.length === 0 ? (
        <div className="no-pets">
          <p>No pets found matching your criteria.</p>
          <button onClick={clearAllFilters} className="clear-filters-btn">
            Clear Filters
          </button>
        </div>
      ) : (
        <>
          <div className="results-count">
            Found {pets.length} pet{pets.length !== 1 ? 's' : ''}
          </div>
          <div className="pets-grid">
            {pets.map((pet) => (
              <div key={pet._id} className="pet-card">
                <img src={pet.imageUrl} alt={pet.name} className="pet-card-image" />
                <div className="pet-card-content">
                  <h3>{pet.name}</h3>
                  <p>{pet.breed} • {pet.age} years • {pet.gender}</p>
                  <p className="pet-price">${pet.adoptionFee}</p>
                  <Link to={`/pets/${pet._id}`} className="details-btn">
                    View Details
                  </Link>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default AllPets;
